-- La fiche signée : date de signature et prochaine action datées d'aujourd'hui.
update public.prospects set signed_at = now() - interval '5 days' where status = 'signe' and signed_at is null and id::text like '10000000-%';
update public.prospects set next_action_at = current_date + ((abs(hashtext(id::text)) % 3))::int where next_action is not null and next_action_at is null and id::text like '10000000-%';
